-- ── crm ─────────────────────────────────────────────────────────────────────
ALTER TABLE crm.customer
  ADD CONSTRAINT customer_kind_valid CHECK (kind IN ('individual', 'company')),
  ADD CONSTRAINT customer_phone_format CHECK (phone ~ '^\+?[0-9][0-9 -]{5,19}$');
ALTER TABLE crm.vehicle
  ADD CONSTRAINT vehicle_plate_format CHECK (plate = upper(plate) AND plate ~ '^\S(.*\S)?$' AND length(plate) <= 20),
  ADD CONSTRAINT vehicle_vin_format CHECK (vin IS NULL OR vin ~ '^[A-HJ-NPR-Z0-9]{17}$'),
  ADD CONSTRAINT vehicle_year_plausible CHECK (year IS NULL OR year BETWEEN 1950 AND 2100);

-- ── workshop ────────────────────────────────────────────────────────────────
ALTER TABLE workshop.job_card
  ADD CONSTRAINT job_status_valid CHECK (status IN
    ('draft', 'approved', 'assigned', 'in_progress', 'rework', 'qc', 'ready', 'delivered', 'cancelled')),
  ADD CONSTRAINT job_fuel_level_valid CHECK (fuel_level IN ('empty', 'quarter', 'half', 'three_quarters', 'full')),
  ADD CONSTRAINT job_odometer_valid CHECK (odometer_in >= 0 AND (odometer_out IS NULL OR odometer_out >= odometer_in)),
  -- Work past the draft stage must carry the customer's authorisation (WMS-005 without prices).
  ADD CONSTRAINT job_authorized_after_draft CHECK (
    status IN ('draft', 'cancelled')
    OR (authorized_by_name IS NOT NULL AND authorized_via IN ('in_person', 'phone', 'written')
        AND authorized_at IS NOT NULL AND authorization_recorded_by IS NOT NULL)),
  ADD CONSTRAINT job_delivered_complete CHECK (
    status <> 'delivered' OR (delivered_to_name IS NOT NULL AND delivered_at IS NOT NULL AND odometer_out IS NOT NULL)),
  ADD CONSTRAINT job_cancelled_has_reason CHECK (status <> 'cancelled' OR cancelled_reason IS NOT NULL),
  ADD CONSTRAINT job_rework_count_valid CHECK (rework_count >= 0);

ALTER TABLE workshop.job_task
  ADD CONSTRAINT job_task_status_valid CHECK (status IN ('open', 'done')),
  ADD CONSTRAINT job_task_hours_positive CHECK (estimated_hours > 0),
  ADD CONSTRAINT job_task_done_complete CHECK ((status = 'done') = (done_at IS NOT NULL AND done_by IS NOT NULL));

ALTER TABLE workshop.job_event
  ADD CONSTRAINT job_event_kind_valid CHECK (kind IN ('created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated'));

-- The timeline is append-only, like the audit trail.
CREATE TRIGGER job_event_immutable BEFORE UPDATE OR DELETE ON workshop.job_event
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();
-- Delivered and cancelled jobs are closed records.
CREATE OR REPLACE FUNCTION workshop.guard_closed_job() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status IN ('delivered', 'cancelled') THEN
    RAISE EXCEPTION 'ERP: job % is % and cannot be changed', OLD.number, OLD.status
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_card_closed BEFORE UPDATE OR DELETE ON workshop.job_card
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_closed_job();

-- ── notifications for the workshop ──────────────────────────────────────────
ALTER TABLE platform.notification DROP CONSTRAINT notification_kind_valid;
ALTER TABLE platform.notification ADD CONSTRAINT notification_kind_valid CHECK (kind IN (
  'journal_reversed', 'role_granted', 'role_revoked', 'role_changed', 'period_closed',
  'export_ready', 'export_failed', 'job_assigned', 'job_rework', 'job_ready'));

-- ── permissions: company administrators receive the new ones (as new companies do) ────────────
UPDATE iam.role
   SET permissions = (
         SELECT array_agg(DISTINCT p ORDER BY p)
           FROM unnest(permissions || ARRAY['crm.customer.read', 'crm.customer.manage', 'workshop.job.read',
                                            'workshop.job.manage', 'workshop.job.work', 'workshop.job.qc']) AS p),
       version = version + 1,
       updated_at = now()
 WHERE is_system AND code = 'company-admin';
